def solve(inputs: dict) -> float:
    matrix = inputs['matrix']
    power = inputs['power']
    modulus = inputs['modulus']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        n = len(A)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, exp, mod):
        """Compute M^exp modulo mod using fast exponentiation"""
        n = len(M)
        # Initialize result as identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]

        base = [row[:] for row in M]  # Copy M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result = matrix_pow(matrix, power, modulus)

    # Sum all entries
    total = sum(result[i][j] for i in range(len(result)) for j in range(len(result[0])))

    return float(total % modulus)

